import { useRef, useLayoutEffect, useState } from 'react';
import { useWindowSize } from '../hooks/index.js';
import { INITIAL_STYLE, DEFAULT_PLACEMENT } from './constants.js';
import { calculatePosition } from './calculatePosition.js';
export const usePopoverPosition = ({ placement = DEFAULT_PLACEMENT, anchorRef, style: propsStyle })=>{
    const popoverRef = useRef(null);
    const wrapperRef = useRef(null);
    const [popoverStyle, setPopoverStyle] = useState(INITIAL_STYLE);
    const [windowWidth, windowHeight] = useWindowSize();
    useLayoutEffect(()=>{
        if (!anchorRef.current || !popoverRef.current || !wrapperRef.current) return;
        const anchorRect = anchorRef.current.getBoundingClientRect();
        const popoverRect = popoverRef.current.getBoundingClientRect();
        const wrapperRect = wrapperRef.current.getBoundingClientRect();
        const position = calculatePosition(anchorRect, popoverRect, wrapperRect, placement);
        setPopoverStyle(position);
    }, [
        anchorRef,
        placement,
        windowWidth,
        windowHeight
    ]);
    const style = {
        ...propsStyle,
        ...popoverStyle
    };
    return {
        popoverRef,
        wrapperRef,
        style
    };
};
